 94→// runStatusDetailed shows the effective status plus detailed status for each settings file.
 95→func runStatusDetailed(w io.Writer, settingsPath, localSettingsPath string, projectExists, localExists bool) error {
 96→	// First show the effective/merged status
 97→	effectiveSettings, err := LoadEntireSettings()
 98→	if err != nil {
 99→		return fmt.Errorf("failed to load settings: %w", err)
100→	}
101→	fmt.Fprintln(w, formatSettingsStatusShort(effectiveSettings))
102→	fmt.Fprintln(w) // blank line
103→
104→	// Show project settings if it exists
105→	if projectExists {
106→		projectSettings, err := settings.LoadFromFile(settingsPath)
107→		if err != nil {
108→			return fmt.Errorf("failed to load project settings: %w", err)
109→		}
110→		fmt.Fprintln(w, formatSettingsStatus("Project", projectSettings))
111→	}
112→
113→	// Show local settings if it exists
114→	if localExists {
115→		localSettings, err := settings.LoadFromFile(localSettingsPath)
116→		if err != nil {
117→			return fmt.Errorf("failed to load local settings: %w", err)
118→		}
119→		fmt.Fprintln(w, formatSettingsStatus("Local", localSettings))
120→	}
121→
122→	if effectiveSettings.Enabled {
123→		writeActiveSessions(w)
124→	}
125→
126→	return nil
127→}
